contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint firstVal, uint secondVal) public payable {
        require(true);

        bool preInitReverted;
        c.SetMinSum(firstVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) { preInitReverted = true; } else { preInitReverted = false; }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool postInitReverted;
        c.SetMinSum(secondVal); bool __rev1 = __ESBMC_reverted(); if (__rev1) { postInitReverted = true; } else { postInitReverted = false; }

        assert(!preInitReverted && postInitReverted && c.MinSum() == firstVal);
    }
}

