// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 firstVal, uint256 secondVal) internal {
        vm.assume(true);
        bool preInitReverted;
        try c.SetMinSum(firstVal) { preInitReverted = false; } catch { preInitReverted = true; }
        try c.Initialized() {} catch { return; }
        bool postInitReverted;
        try c.SetMinSum(secondVal) { postInitReverted = false; } catch { postInitReverted = true; }
        assertTrue(!preInitReverted && postInitReverted && c.MinSum() == firstVal);
    }

    function testFuzz_run(uint256 firstVal, uint256 secondVal) public {
        _run(firstVal, secondVal);
    }

    receive() external payable {}
}
